using AdDatabase.BLL.Entities; using AdDatabase.BLL.Interfaces; using AdDatabase.BLL.Models; using AdDatabase.DAL.Data; using Microsoft.EntityFrameworkCore; using System.Linq.Expressions;
namespace AdDatabase.DAL.Repositories;
public class GenericRepository<T>(ApplicationDbContext db):IGenericRepository<T> where T:class { protected readonly ApplicationDbContext Db=db; protected DbSet<T> Set=>Db.Set<T>(); public virtual Task<T?> GetByIdAsync(int id,CancellationToken ct=default)=>Set.FindAsync([id],ct).AsTask(); public Task<List<T>> ListAsync(Expression<Func<T,bool>>? p=null,CancellationToken ct=default)=>(p is null?Set.AsQueryable():Set.Where(p)).AsNoTracking().ToListAsync(ct); public Task<bool> ExistsAsync(Expression<Func<T,bool>> p,CancellationToken ct=default)=>Set.AnyAsync(p,ct); public Task AddAsync(T e,CancellationToken ct=default)=>Set.AddAsync(e,ct).AsTask(); public void Update(T e)=>Set.Update(e); public void Remove(T e)=>Set.Remove(e); public Task<int> SaveChangesAsync(CancellationToken ct=default)=>Db.SaveChangesAsync(ct); }
public class AdRepository(ApplicationDbContext db):GenericRepository<Ad>(db),IAdRepository { public Task<Ad?> GetDetailsAsync(int id,CancellationToken ct=default)=>Db.Ads.AsSplitQuery().Include(x=>x.User).ThenInclude(x=>x!.Profile).Include(x=>x.Category).Include(x=>x.Region).ThenInclude(x=>x!.City).Include(x=>x.Images).Include(x=>x.Attributes).Include(x=>x.AdTags).ThenInclude(x=>x.Tag).SingleOrDefaultAsync(x=>x.Id==id,ct); public async Task<PagedResult<Ad>> SearchAsync(AdFilter f,CancellationToken ct=default){var q=Db.Ads.AsNoTracking().Where(x=>x.Status=="Active");if(f.CategoryId.HasValue)q=q.Where(x=>x.CategoryId==f.CategoryId);if(f.RegionId.HasValue)q=q.Where(x=>x.RegionId==f.RegionId);if(f.MinPrice.HasValue)q=q.Where(x=>x.Price>=f.MinPrice);if(f.MaxPrice.HasValue)q=q.Where(x=>x.Price<=f.MaxPrice);if(!string.IsNullOrWhiteSpace(f.Search))q=q.Where(x=>x.Title.Contains(f.Search)||x.Description.Contains(f.Search));var total=await q.CountAsync(ct);var p=Math.Max(1,f.Page);var size=Math.Clamp(f.PageSize,1,100);var rows=await q.OrderByDescending(x=>x.CreatedAt).Skip((p-1)*size).Take(size).Include(x=>x.Images.Where(i=>i.IsPrimary)).Include(x=>x.Region).Include(x=>x.Category).AsSplitQuery().ToListAsync(ct);return new(rows,p,size,total);}}
public class ConversationRepository(ApplicationDbContext db):GenericRepository<Conversation>(db),IConversationRepository { public Task<List<Conversation>> GetForUserAsync(int u,CancellationToken ct=default)=>Db.Conversations.AsNoTracking().Where(x=>x.BuyerUserId==u||x.SellerUserId==u).OrderByDescending(x=>x.LastMessageAt).ToListAsync(ct);public Task<Conversation?> GetWithMessagesAsync(int id,CancellationToken ct=default)=>Db.Conversations.AsNoTracking().Include(x=>x.Messages.OrderBy(m=>m.CreatedAt)).ThenInclude(x=>x.Attachments).SingleOrDefaultAsync(x=>x.Id==id,ct);}
public class UnitOfWork(ApplicationDbContext db):IUnitOfWork { public IGenericRepository<User> Users {get;}=new GenericRepository<User>(db);public IGenericRepository<Category> Categories {get;}=new GenericRepository<Category>(db);public IGenericRepository<Region> Regions {get;}=new GenericRepository<Region>(db);public IGenericRepository<Comment> Comments {get;}=new GenericRepository<Comment>(db);public IGenericRepository<Notification> Notifications {get;}=new GenericRepository<Notification>(db);public IGenericRepository<AdFavorite> Favorites {get;}=new GenericRepository<AdFavorite>(db);public IGenericRepository<Rating> Ratings {get;}=new GenericRepository<Rating>(db);public IAdRepository Ads {get;}=new AdRepository(db);public IConversationRepository Conversations {get;}=new ConversationRepository(db);public IGenericRepository<Message> Messages {get;}=new GenericRepository<Message>(db);public Task<int> SaveChangesAsync(CancellationToken ct=default)=>db.SaveChangesAsync(ct); }
